/* ───────────────────────────── Labs ───────────────────────────── */

const LAB_SELECT = '*, lab_members(id, lab_id, user_id, full_name, title, role, term, can_edit, sort_order, is_past, graduation_year)';

export function useLabs() {
  return useQuery({ queryKey: qk.labs, staleTime: 60_000, queryFn: () => rows<Lab[]>(db.from('labs').select(LAB_SELECT).order('name')) });
}

export function useLab(slug: string) {
  return useQuery({ queryKey: qk.lab(slug), queryFn: () => rows<Lab | null>(db.from('labs').select(LAB_SELECT).eq('slug', slug).maybeSingle()) });
}

export function useLabInternal(labId: string | undefined, enabled: boolean) {
  return useQuery({
    queryKey: qk.labInternal(labId ?? ''),
    enabled: !!labId && enabled,
    queryFn: () => rows<LabInternal | null>(db.from('lab_internal').select('*').eq('lab_id', labId).maybeSingle()),
  });
}

export type LabContact = { member_id: string; email: string | null; contact: string | null };
export function useLabContacts(labId: string | undefined, enabled: boolean) {
  return useQuery({
    queryKey: qk.labContacts(labId ?? ''),
    enabled: !!labId && enabled,
    queryFn: () => rows<LabContact[]>(db.from('lab_member_contacts').select('member_id, email, contact, lab_members!inner(lab_id)').eq('lab_members.lab_id', labId)),
  });
}

export type LabPatch = Partial<Omit<Lab, 'id' | 'slug' | 'lab_members' | 'updated_at'>>;

function invalidateLabs(qc: ReturnType<typeof useQueryClient>) {
  void qc.invalidateQueries({ queryKey: qk.labs });
  void qc.invalidateQueries({ queryKey: ['lab'] });
  void qc.invalidateQueries({ queryKey: ['lab-contacts'] });
}

/** Add a person to a lab by name and/or e-mail (links the account when it exists). Checked by add_lab_member(). */
export function useAddLabMember() {
  const qc = useQueryClient();
  return useMutation({
    mutationFn: async (v: { labId: string; fullName: string; email: string; role: LabRole; title: string }) => {
      const { data, error } = await db.rpc('add_lab_member', { p_lab: v.labId, p_full_name: v.fullName, p_email: v.email, p_role: v.role, p_title: v.title });
      if (error) fail(error);
      return data as { id: string; linked: boolean };
    },
    onSuccess: () => invalidateLabs(qc),
  });
}

/** Change a member's position / title. Rights follow the position (database trigger); head positions are protected. */
export function useUpdateLabMember() {
  const qc = useQueryClient();
  return useMutation({
    mutationFn: async (v: { id: string; role?: LabRole; title?: string | null }) => {
      const patch: Record<string, unknown> = {};
      if (v.role) patch['role'] = v.role;
      if (v.title !== undefined) patch['title'] = v.title?.trim() || null;
      const { data, error } = await db.from('lab_members').update(patch).eq('id', v.id).select('id');
      if (error) fail(error);
      if (!data?.length) throw new Error('NOT_ALLOWED: you cannot change this member');
    },
    onSuccess: () => invalidateLabs(qc),
  });
}

export function useRemoveLabMember() {
  const qc = useQueryClient();
  return useMutation({
    mutationFn: async (id: string) => {
      const { data, error } = await db.from('lab_members').delete().eq('id', id).select('id');
      if (error) fail(error);
      if (!data?.length) throw new Error('NOT_ALLOWED: you cannot remove this member');
    },
    onSuccess: () => invalidateLabs(qc),
  });
}

/* ───────────── People (public contacts) ───────────── */

/** Registered person as other signed-in users see them: name, primary role, e-mail (no phone, no CV). */
export type Person = {
  id: string; first_name: string; last_name: string; role: string; email: string;
  course: number | null; major: string | null; department: string | null; position: string | null; bio: string | null;
  faculty?: string | null; group_name?: string | null; avatar_url?: string | null; personal_email?: string | null;
};

export function usePeople(ids: string[], enabled = true) {
  const key = [...new Set(ids)].sort();
  return useQuery({
    queryKey: ['people', ...key],
    enabled: enabled && key.length > 0,
    staleTime: 60_000,
    queryFn: () => rows<Person[]>(db.from('public_people').select('*').in('id', key)),
  });
}

export function usePerson(id: string, enabled = true) {
  return useQuery({
    queryKey: ['person', id],
    enabled: enabled && !!id,
    queryFn: async () => {
      const person = await rows<Person | null>(db.from('public_people').select('*').eq('id', id).maybeSingle());
      const labs = await rows<{ role: LabRole; title: string | null; labs: { name: string; slug: string } | null }[]>(
        db.from('lab_members').select('role, title, labs(name, slug)').eq('user_id', id).neq('role', 'former_lead'),
      );
      return person ? { person, labs } : null;
    },
  });
}

export const personName = (p: Pick<Person, 'first_name' | 'last_name' | 'email'>) => `${p.first_name} ${p.last_name}`.trim() || p.email;

/** Search registered users by name or e-mail (signed-in users only). */
export function useSearchPeople(q: string) {
  const term = q.trim().replace(/[%,()]/g, ' ').trim();
  return useQuery({
    queryKey: ['people-search', term],
    enabled: term.length >= 2,
    staleTime: 30_000,
    queryFn: () =>
      rows<Person[]>(
        db.from('public_people').select('*')
          .or(`first_name.ilike.%${term}%,last_name.ilike.%${term}%,email.ilike.%${term}%`)
          .order('last_name').limit(12),
      ),
  });
}

/* ───────────── Coordinator tools ───────────── */

export function useAdminLabActions() {
  const qc = useQueryClient();
  const done = () => invalidateLabs(qc);
  const call = async (fn: string, args: Record<string, unknown>) => {
    const { data, error } = await db.rpc(fn, args);
    if (error) fail(error);
    return data as unknown;
  };
  return {
    createLab: useMutation({ mutationFn: (v: { name: string; focus: string[] }) => call('admin_create_lab', { p_name: v.name, p_focus: v.focus }), onSuccess: done }),
    deleteLab: useMutation({
      mutationFn: async (id: string) => {
        const { data, error } = await db.from('labs').delete().eq('id', id).select('id');
        if (error) fail(error);
        if (!data?.length) throw new Error('NOT_ALLOWED: coordinator only');
      },
      onSuccess: done,
    }),
    assignHead: useMutation({ mutationFn: (v: { labId: string; userId: string }) => call('assign_lab_head', { p_lab: v.labId, p_user: v.userId }), onSuccess: done }),
    removeHead: useMutation({ mutationFn: (v: { labId: string; userId: string }) => call('remove_lab_head', { p_lab: v.labId, p_user: v.userId }), onSuccess: done }),
  };
}

