/** Lab leader first setup: what is still missing on the lab page. */
export function labSetupSteps(lab: Lab) {
  const team = lab.lab_members.filter((m) => m.role !== 'former_lead');
  return [
    { key: 'description', label: 'Description', done: lab.description.trim().length >= 40 },
    { key: 'areas', label: 'Research areas', done: lab.focus.length > 0 && lab.tags.length > 0 },
    { key: 'skills', label: 'Skills', done: (lab.skills ?? []).length > 0 },
    { key: 'contacts', label: 'Contacts & location', done: !!lab.location.trim() && (!!lab.contact_email || !!lab.website || lab.social_links.length > 0) },
    { key: 'team', label: 'Team (2+ people)', done: team.length >= 2 },
  ] as const;
}
export type MemberDraft = { id?: string; full_name: string; title: string; role: LabRole; term: string; email: string; contact: string; is_past?: boolean; graduation_year?: string };
export type ProjectDraft = { id?: string; title: string; kind: ProjectKind; status: ProjectStatus; summary: string; year: string; github_url: string; demo_url: string; paper_url: string; tags: string };

export async function saveLab(
  lab: Lab,
  patch: LabPatch,
  internal: Omit<LabInternal, 'lab_id'>,
  members: MemberDraft[],
  projects: { drafts: ProjectDraft[]; removed: string[] },
  userId: string,
) {
  const { error } = await db.from('labs').update({ ...patch, updated_by: userId }).eq('id', lab.id);
  if (error) fail(error);
  const { error: iErr } = await db.from('lab_internal').upsert({ lab_id: lab.id, ...internal, updated_by: userId });
  if (iErr) fail(iErr);

  const keep = new Set(members.map((m) => m.id).filter(Boolean));
  const removed = lab.lab_members.filter((m) => !keep.has(m.id)).map((m) => m.id);
  if (removed.length) {
    const { error: dErr } = await db.from('lab_members').delete().in('id', removed);
    if (dErr) fail(dErr);
  }
  for (const [i, m] of members.entries()) {
    const gy = Number(m.graduation_year);
    const row = {
      full_name: m.full_name.trim(), title: m.title.trim() || null, role: m.role, term: m.term.trim() || null, sort_order: i,
      is_past: !!m.is_past, graduation_year: m.is_past && Number.isInteger(gy) && gy >= 1990 && gy <= 2100 ? gy : null,
    };
    const before = m.id ? lab.lab_members.find((x) => x.id === m.id) : undefined;
    // Unchanged rows are skipped, so a student lead can save the form without touching protected head rows.
    const same = before && before.full_name === row.full_name && (before.title ?? null) === row.title && before.role === row.role && (before.term ?? null) === row.term
      && before.sort_order === row.sort_order && !!before.is_past === row.is_past && (before.graduation_year ?? null) === row.graduation_year;
    const res = m.id
      ? same
        ? { data: { id: m.id }, error: null }
        : await db.from('lab_members').update(row).eq('id', m.id).select('id').single()
      : await db.from('lab_members').insert({ lab_id: lab.id, ...row }).select('id').single();
    if (res.error) fail(res.error);
    const memberId = (res.data as { id: string }).id;
    if (m.email.trim() || m.contact.trim()) {
      const { error: cErr } = await db.from('lab_member_contacts').upsert({ member_id: memberId, email: m.email.trim().toLowerCase() || null, contact: m.contact.trim() || null });
      if (cErr) fail(cErr);
    }
  }

  if (projects.removed.length) {
    const { error: pErr } = await db.from('projects').delete().in('id', projects.removed);
    if (pErr) fail(pErr);
  }
  for (const [i, p] of projects.drafts.entries()) {
    const yr = Number(p.year);
    const row = {
      lab_id: lab.id,
      title: p.title.trim(),
      kind: p.kind,
      status: p.status,
      summary: p.summary.trim() || null,
      year: Number.isInteger(yr) && yr > 1990 ? yr : null,
      github_url: p.github_url.trim() || null,
      demo_url: p.demo_url.trim() || null,
      paper_url: p.paper_url.trim() || null,
      tags: p.tags.split(',').map((t) => t.trim()).filter(Boolean).slice(0, 8),
      sort_order: i,
    };
    const res = p.id ? await db.from('projects').update(row).eq('id', p.id) : await db.from('projects').insert(row);
    if (res.error) fail(res.error);
  }
}

export async function uploadLabImage(labId: string, file: File, folder: string) {
  const ext = (file.name.split('.').pop() ?? 'jpg').toLowerCase().replace(/[^a-z0-9]/g, '');
  const path = `${labId}/${folder}/${Date.now()}-${Math.random().toString(36).slice(2, 7)}.${ext}`;
  const { error } = await db.storage.from('lab-assets').upload(path, file, { contentType: file.type, upsert: false });
  if (error) fail(error);
  return db.storage.from('lab-assets').getPublicUrl(path).data.publicUrl as string;
}

export async function signedUrl(path: string) {
  const { data, error } = await db.storage.from('cvs').createSignedUrl(path, 120);
  if (error || !data?.signedUrl) fail(error ?? { message: 'File not found' });
  return data.signedUrl as string;
}

export function useToggleSavedLab(userId: string | undefined, saved: string[], onChange: () => void) {
  return useMutation({
    mutationFn: async (labId: string) => {
      if (!userId) throw new Error('AUTH_REQUIRED: sign in to save labs');
      const has = saved.includes(labId);
      const { error } = has ? await db.from('saved_labs').delete().eq('user_id', userId).eq('lab_id', labId) : await db.from('saved_labs').insert({ user_id: userId, lab_id: labId });
      if (error) fail(error);
      return !has;
    },
    onSuccess: onChange,
  });
}

