export const MAX_CV_BYTES = 5 * 1024 * 1024;

export function cvProblem(file: File | null | undefined): string | null {
  if (!file) return 'Attach your CV as a PDF.';
  if (file.type !== 'application/pdf' && !file.name.toLowerCase().endsWith('.pdf')) return 'The CV must be a PDF file.';
  if (file.size > MAX_CV_BYTES) return 'The CV must be 5 MB or smaller.';
  return null;
}

/** Profile CV: cvs/{uid}/cv.pdf (a storage trigger marks profiles.cv_path). */
export async function uploadCv(userId: string, file: File) {
  const { error } = await db.storage.from('cvs').upload(`${userId}/cv.pdf`, file, { upsert: true, contentType: 'application/pdf' });
  if (error) fail(error);
  await db.from('profiles').update({ cv_filename: file.name.slice(0, 120) }).eq('id', userId);
}

/** Profile photo: avatars/{uid}/… (public bucket). Returns the public URL saved on the profile. */
export async function uploadAvatar(userId: string, file: File) {
  if (!/^image\/(png|jpeg|webp)$/.test(file.type)) throw new Error('BAD_FILE: use a PNG, JPG or WebP image');
  if (file.size > 3 * 1024 * 1024) throw new Error('TOO_BIG: the photo must be 3 MB or smaller');
  const ext = file.type === 'image/png' ? 'png' : file.type === 'image/webp' ? 'webp' : 'jpg';
  const path = `${userId}/avatar-${Date.now()}.${ext}`;
  const { error } = await db.storage.from('avatars').upload(path, file, { upsert: true, contentType: file.type });
  if (error) fail(error);
  const url = db.storage.from('avatars').getPublicUrl(path).data.publicUrl as string;
  const { error: pErr } = await db.from('profiles').update({ avatar_url: url }).eq('id', userId);
  if (pErr) fail(pErr);
  return url;
}

/** A CV used only for one application; the profile CV stays as it is. */
export async function uploadApplicationCv(userId: string, file: File) {
  const path = `${userId}/apply-${Date.now()}.pdf`;
  const { error } = await db.storage.from('cvs').upload(path, file, { upsert: false, contentType: 'application/pdf' });
  if (error) fail(error);
  return path;
}

