/* ───────────── External events, competitions & hackathons (v10) ───────────── */

export type ExternalKind = 'competition' | 'hackathon' | 'olympiad' | 'conference' | 'festival' | 'other';
export const EXTERNAL_KIND_LABEL: Record<ExternalKind, string> = {
  competition: 'Competition', hackathon: 'Hackathon', olympiad: 'Olympiad', conference: 'Conference', festival: 'Festival', other: 'Event',
};
/** An annual (recurring) event: every edition links back to it. */
export type EventSeries = { id: string; title: string; kind: ExternalKind; organizer: string | null; website: string | null; recurrence: 'annual' };
export type ParticipantRole = 'student' | 'mentor';
export type ExternalParticipant = { id: string; member_id: string | null; full_name: string; role: ParticipantRole; sort_order: number };
/** One lab taking part: "Participating" before the event, result + submitted project after it. */
export type ExternalEntry = {
  id: string; event_id: string; lab_id: string;
  result: string | null; project_title: string | null; project_url: string | null; project_id: string | null; notes: string | null;
  labs: { name: string; slug: string } | null;
  external_event_people: ExternalParticipant[];
};
export type ExternalEvent = {
  id: string; series_id: string | null; kind: ExternalKind; title: string; organizer: string | null; location: string | null; url: string | null;
  starts_on: string | null; ends_on: string | null; year: number | null; description: string | null; created_by: string | null;
  poster_url?: string | null;
  /** v12: where it happens and whether SDU co-hosts it */
  location_type?: 'sdu' | 'outside' | 'online';
  cohosted?: boolean;
  event_series: EventSeries | null;
  external_event_labs: ExternalEntry[];
};

/** Today's date (YYYY-MM-DD) in SDU's time zone. `toISOString()` gives the UTC date, which is still "yesterday"
 *  in Almaty between 00:00 and 05:00. */
export const SITAM_TIME_ZONE = 'Asia/Almaty';
export function sitamDay(d = new Date()) {
  return new Intl.DateTimeFormat('en-CA', { timeZone: SITAM_TIME_ZONE, year: 'numeric', month: '2-digit', day: '2-digit' }).format(d);
}
const sitamYear = (d: Date) => Number(sitamDay(d).slice(0, 4));

/** Upcoming = has not ended yet. Events with only a year (no dates) count as past once that year is over. */
export function isUpcomingExternal(e: Pick<ExternalEvent, 'starts_on' | 'ends_on' | 'year'>, today = new Date()) {
  const day = sitamDay(today);
  if (e.ends_on) return e.ends_on >= day;
  if (e.starts_on) return e.starts_on >= day;
  return e.year !== null && e.year >= sitamYear(today);
}
/** Started = the first day has come. Events with only a year count as started from the start of that year. */
export function hasStartedExternal(e: Pick<ExternalEvent, 'starts_on' | 'year'>, today = new Date()) {
  if (e.starts_on) return e.starts_on <= sitamDay(today);
  return e.year === null || e.year <= sitamYear(today);
}
export function externalDates(e: Pick<ExternalEvent, 'starts_on' | 'ends_on' | 'year'>) {
  const f = (d: string) => new Date(`${d}T00:00:00`).toLocaleDateString('en-GB', { day: 'numeric', month: 'short', year: 'numeric' });
  if (e.starts_on && e.ends_on && e.ends_on !== e.starts_on) return `${f(e.starts_on)} – ${f(e.ends_on)}`;
  if (e.starts_on) return f(e.starts_on);
  return e.year ? String(e.year) : 'Date not specified';
}

