/* ───────────────────────────── Industry partners (v12) ───────────────────────────── */
export type IndustryPartner = {
  id: string; name: string; short_name: string | null; logo_url: string | null; website: string | null; ceo: string | null;
  founded_year: number | null; sdu_alumni: string[]; upcoming_projects: string[]; completed_projects: string[]; lab_ids: string[]; sort_order: number;
};
export type IndustryPartnerDraft = Omit<IndustryPartner, 'id'> & { id: string | null };
const partnersKey = ['industry-partners'] as const;
export function useIndustryPartners() {
  return useQuery({
    queryKey: partnersKey, staleTime: 60_000,
    queryFn: () => rows<IndustryPartner[]>(db.from('industry_partners').select('*').order('sort_order').order('name')),
  });
}
/** Coordinator only (row-level security on industry_partners). */
export function useSavePartner() {
  const qc = useQueryClient();
  return useMutation({
    mutationFn: async (d: IndustryPartnerDraft) => {
      const { id, ...row } = d;
      const { error } = id ? await db.from('industry_partners').update({ ...row, updated_at: new Date().toISOString() }).eq('id', id) : await db.from('industry_partners').insert(row);
      if (error) fail(error);
    },
    onSuccess: () => void qc.invalidateQueries({ queryKey: partnersKey }),
  });
}
export function useDeletePartner() {
  const qc = useQueryClient();
  return useMutation({
    mutationFn: async (id: string) => { const { error } = await db.from('industry_partners').delete().eq('id', id); if (error) fail(error); },
    onSuccess: () => void qc.invalidateQueries({ queryKey: partnersKey }),
  });
}
/** v12, coordinator only (trigger labs_kind_guard): laboratory or student community. */
export function useSetLabKind() {
  const qc = useQueryClient();
  return useMutation({
    mutationFn: async (v: { id: string; kind: 'lab' | 'community' }) => { const { error } = await db.from('labs').update({ kind: v.kind }).eq('id', v.id); if (error) fail(error); },
    onSuccess: () => void qc.invalidateQueries({ queryKey: qk.labs }),
  });
}

/* ───────────────────────────── Research publications ───────────────────────────── */

const PROF_COLS = 'id, username, first_name, last_name, full_name, job_title, degree, photo_url, orcid_url, scopus_id, scholar_url, h_index, i10_index, total_citations, total_works, keywords, topics';
const PUB_COLS = 'id, title, year, type, doi, venue, publisher, citations, is_open_access, url, keywords, publication_authors(professors(username, full_name))';

export function useProfessors() {
  return useQuery({ queryKey: qk.professors, staleTime: 300_000, queryFn: () => rows<Professor[]>(db.from('professors').select(PROF_COLS).order('last_name')) });
}

export function usePublications() {
  return useQuery({ queryKey: qk.publications, staleTime: 300_000, queryFn: () => rows<Publication[]>(db.from('publications').select(PUB_COLS).order('year', { ascending: false, nullsFirst: false }).order('citations', { ascending: false })) });
}

export function useProfessor(username: string) {
  return useQuery({
    queryKey: qk.professor(username),
    enabled: !!username,
    queryFn: async () => {
      const prof = await rows<Professor | null>(db.from('professors').select(PROF_COLS).eq('username', username).maybeSingle());
      if (!prof) return null;
      const links = await rows<{ publications: Publication | null }[]>(db.from('publication_authors').select(`publications(${PUB_COLS})`).eq('professor_id', prof.id));
      const pubs = links.map((l) => l.publications).filter((p): p is Publication => !!p).sort((a, b) => (b.year ?? 0) - (a.year ?? 0) || b.citations - a.citations);
      const labs = await rows<{ role: LabRole; title: string | null; labs: { name: string; slug: string } | null }[]>(
        db.from('lab_members').select('role, title, labs(name, slug)').ilike('full_name', prof.full_name),
      );
      // E-mail is readable for signed-in users only (column grant), so it is fetched on its own.
      const { data: contact } = await db.from('professors').select('email').eq('id', prof.id).maybeSingle();
      return { prof, pubs, labs, email: ((contact as { email: string | null } | null)?.email ?? null) as string | null };
    },
  });
}

