export function hostNames(hosts: Host[]): string {
  return hosts.map((h) => h.labs?.name ?? h.companies?.name ?? h.projects?.title ?? h.person_name).filter(Boolean).join(' · ') || 'SITAM';
}

export function eventDate(iso: string) {
  const d = new Date(iso);
  const f = (o: Intl.DateTimeFormatOptions) => d.toLocaleDateString('en-GB', { ...o, timeZone: 'Asia/Almaty' });
  return {
    day: f({ day: 'numeric' }),
    month: f({ month: 'short' }).toUpperCase(),
    weekday: f({ weekday: 'short' }).toUpperCase(),
    long: f({ weekday: 'long', day: 'numeric', month: 'long' }),
    short: f({ day: 'numeric', month: 'short', year: 'numeric' }),
    time: d.toLocaleTimeString('en-GB', { hour: '2-digit', minute: '2-digit', timeZone: 'Asia/Almaty' }),
  };
}

export function formatDate(iso: string, opts: Intl.DateTimeFormatOptions = { day: 'numeric', month: 'short', year: 'numeric' }) {
  return new Date(iso.length === 10 ? `${iso}T00:00:00Z` : iso).toLocaleDateString('en-GB', { ...opts, timeZone: 'UTC' });
}

/** Monday 00:00 → next Monday 00:00 in Almaty time (UTC+5), as epoch ms. */
export function currentWeekRange(now = new Date()) {
  const local = new Date(now.getTime() + 5 * 3_600_000);
  const dow = (local.getUTCDay() + 6) % 7;
  const monday = Date.UTC(local.getUTCFullYear(), local.getUTCMonth(), local.getUTCDate() - dow) - 5 * 3_600_000;
  return { start: monday, end: monday + 7 * 86_400_000 };
}
